package io.github.diodeme.ji.security.secret;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermission;
import java.util.Set;

/** Reads a dedicated POSIX owner-only secret file and rejects links or broader permissions. */
public final class FileSecretSource implements SecretSource {
    private static final Set<PosixFilePermission> OWNER_ONLY = Set.of(
            PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE);

    @Override
    public SecretValue read(String reference) {
        Path path = Path.of(reference);
        try {
            if (Files.isSymbolicLink(path) || !Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
                throw new SecurityException("secret file must be a regular non-link file");
            }
            if (!Files.getFileStore(path).supportsFileAttributeView("posix")) {
                throw new UnsupportedOperationException("0600 secret files require POSIX permissions");
            }
            Set<PosixFilePermission> permissions = Files.getPosixFilePermissions(path, LinkOption.NOFOLLOW_LINKS);
            if (!permissions.equals(OWNER_ONLY) && !permissions.equals(Set.of(PosixFilePermission.OWNER_READ))) {
                throw new SecurityException("secret file permissions must be 0600 or 0400");
            }
            return SecretValue.fromBytes(Files.readAllBytes(path));
        } catch (IOException exception) {
            throw new IllegalStateException("secret file is unavailable", exception);
        }
    }
}
